n("n978","s040-04","pater posset esse filius et econtra","la","textual","B om. *econtra*.","certain")
n("n979","s040-06","concurrit ad constitutionem verbi","la","textual","B: *concurrit ad spirationem verbi*, an error anticipating *spiratio* (the parallel *ad constitutionem persone patris* follows in both).","certain")
upd("n689", append=" B: *Sed opi. doctoris est*.")
